package macro;
import star.common.*;import star.base.report.*;import star.flow.*;import java.nio.file.*;import java.io.*;import java.util.*;
public class MiniURANS40Window extends StarMacro {
double v(Simulation s,String n){return s.getReportManager().getReport(n).getReportMonitorValue();}
public void execute(){Simulation s=getActiveSimulation();Path r=Paths.get(s.getSessionPath()).getParent();double start=s.getSolution().getPhysicalTime();String state="CFD_SMOKE_PHYSICAL_PASS_RESIDUAL_REVIEW";try(BufferedWriter w=Files.newBufferedWriter(r.resolve("history.csv"))){if(Math.abs(start)>1e-10)throw new IllegalStateException("ExpectedC0 time0 with saved fields");for(Solver so:s.getSolverManager().getObjects())if((so.getClass().getName().toLowerCase().contains("turb")||so.getClass().getName().contains("SegregatedFlowSolver"))&&so.getFrozen())throw new IllegalStateException("Flow frozen");List<Region> rs=new ArrayList<>(s.getRegionManager().getRegions());List<Boundary> outer=new ArrayList<>(),inlets=new ArrayList<>(),walls=new ArrayList<>();for(Region reg:rs)for(Boundary b:reg.getBoundaryManager().getBoundaries()){if(b.getBoundaryType() instanceof WallBoundary)walls.add(b);if(b.getBoundaryType() instanceof InletBoundary||b.getBoundaryType() instanceof PressureBoundary)outer.add(b);if(b.getBoundaryType() instanceof InletBoundary)inlets.add(b);}MassFlowReport m=s.getReportManager().createReport(MassFlowReport.class),mi=s.getReportManager().createReport(MassFlowReport.class);m.getParts().setObjects(outer);mi.getParts().setObjects(inlets);MinReport pw=s.getReportManager().createReport(MinReport.class);pw.getParts().setObjects(walls);pw.setFieldFunction(s.getFieldFunctionManager().getFunction("AbsolutePressure"));pw.setSmooth(false);List<MinReport> floor=new ArrayList<>();for(String f:List.of("TurbulentKineticEnergy","SpecificDissipationRate")){MinReport q=s.getReportManager().createReport(MinReport.class);q.getParts().setObjects(rs);q.setFieldFunction(s.getFieldFunctionManager().getFunction(f));floor.add(q);}List<MaxReport> caps=new ArrayList<>();for(String f:List.of("Velocity","TurbulentViscosityRatio")){MaxReport q=s.getReportManager().createReport(MaxReport.class);q.getParts().setObjects(rs);FieldFunction ff=s.getFieldFunctionManager().getFunction(f);q.setFieldFunction(f.equals("Velocity")?ff.getMagnitudeFunction():ff);caps.add(q);}
UserFieldFunction ref=s.getFieldFunctionManager().createFieldFunction();ref.setFunctionName("SMOKE_REF");ref.setPresentationName("SMOKE_REF");ref.getTypeOption().setSelected(FieldFunctionTypeOption.Type.VECTOR);Dimensions dd=new Dimensions();dd.setLength(1);ref.setDimensions(dd);ref.setDefinition("$$SavedCoord");XyzInternalTable vt=s.getTableManager().createTable(XyzInternalTable.class);vt.getParts().setObjects(walls);vt.setExtractVertexData(true);vt.setFieldFunctions(List.of(s.getFieldFunctionManager().getFunction("Position").getComponentFunction(0),s.getFieldFunctionManager().getFunction("Position").getComponentFunction(1),s.getFieldFunctionManager().getFunction("Position").getComponentFunction(2)));vt.extract();vt.export(r.resolve("vertices_start.csv").toString(),",");
w.write("time_s,phase_h_rad,delta_deg,delta_dot_rad_s,CL,CD,Mh,Fx,Fz,pABSmin_Pa,mass_relative,solver_s,power_fluid_to_flap_W_per_m\n");long began=System.nanoTime();for(int k=1;k<=40;k++){if(Files.exists(r.getParent().resolve("STOP_MINI.json"))){state="HOLD_STOP_MARKER";break;}long b=System.nanoTime();s.getSimulationIterator().step(1);double sec=(System.nanoTime()-b)/1e9,t=s.getSolution().getPhysicalTime();if(Math.abs(t-(start+.002*k))>1e-9)throw new IllegalStateException("Physical time advance incorrect");double z=Math.min(1,t/.9111060464863853),E=10*Math.pow(z,3)-15*Math.pow(z,4)+6*Math.pow(z,5),Ed=30*z*z*(1-z)*(1-z)/.9111060464863853,theta=13.792434659851589*t,delta=2*E*Math.sin(theta),rate=Math.toRadians(2)*(Ed*Math.sin(theta)+E*13.792434659851589*Math.cos(theta)),cl=v(s,"MINI_CL"),cd=v(s,"MINI_CD"),mh=v(s,"MINI_Mh"),p=Math.min(v(s,"MINI_min_AbsolutePressure"),pw.getReportMonitorValue()),bal=Math.abs(m.getReportMonitorValue())/Math.abs(mi.getReportMonitorValue());w.write(t+","+theta+","+delta+","+rate+","+cl+","+cd+","+mh+","+v(s,"MINI_Fx")+","+v(s,"MINI_Fy")+","+p+","+bal+","+sec+","+(mh*rate)+"\n");w.flush();if(!Double.isFinite(cl+cd+mh+p+bal)||p<=12339.214766776897||bal>1e-4||v(s,"MINI_min_LeastSquaresQuality")<=0||v(s,"MINI_min_Volume")<=0||v(s,"MINI_min_FaceValidity")<.5||floor.stream().anyMatch(q->q.getReportMonitorValue()<=1.0001e-10)||caps.get(0).getReportMonitorValue()>180||caps.get(1).getReportMonitorValue()>=99999){state="HOLD_PHYSICAL";break;}if((System.nanoTime()-began)/1e9>300){state="HOLD_TIME_BUDGET";break;}}
vt.extract();vt.export(r.resolve("vertices_end.csv").toString(),",");boolean residualPass=true;int nmon=0;StringBuilder gates=new StringBuilder("monitor,native_normalized,window_count,maximum_absolute,limit,pass\n");for(Monitor mon:s.getMonitorManager().getObjects())if(mon instanceof ResidualMonitor&&!mon.getPresentationName().equals("Z-momentum")){ResidualMonitor rm=(ResidualMonitor)mon;double[] ys=rm.getAllYValues();double max=0;int count=Math.min(25,ys.length);boolean good=count==25&&rm.isNormalized();for(int q=ys.length-count;q<ys.length;q++){good&=Double.isFinite(ys[q])&&Math.abs(ys[q])<=.01;max=Math.max(max,Math.abs(ys[q]));}residualPass&=good;nmon++;gates.append(rm.getPresentationName()+","+rm.isNormalized()+","+count+","+max+",0.01,"+good+"\n");}residualPass&=nmon==5;Files.writeString(r.resolve("RESIDUAL_WINDOW.csv"),gates.toString());if(state.equals("CFD_SMOKE_PHYSICAL_PASS_RESIDUAL_REVIEW"))state=residualPass?"URANS_SMOKE_PASS_NOT_PERIODIC_VALIDATION":"HOLD_RESIDUAL_WINDOW";
s.saveState(r.resolve("MINI_result.sim").toString());for(Monitor mon:s.getMonitorManager().getObjects())if(mon instanceof ResidualMonitor)mon.export(r.resolve("residual_"+mon.getPresentationName().replaceAll("[^A-Za-z0-9]","_")+".csv").toString());Files.writeString(r.resolve("SOLVE_STATUS.json"),"{\"status\":\""+state+"\",\"time_s\":"+s.getSolution().getPhysicalTime()+",\"flow_active\":true,\"orbital_forcing_active\":false,\"training_approved\":false,\"residual_review_required\":true}");
}catch(Exception e){try{Files.writeString(r.resolve("SMOKE_ERROR.txt"),e.toString());s.saveState(r.resolve("error_checkpoint.sim").toString());}catch(Exception ignored){}throw new RuntimeException(e);}}
}
